#include <iostream>
#include <numeric>
#include <string>
#include <vector>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 0 || n > 1000) return 1;
    std::vector<long long> values;
    for (int i = 0; i < n; i++) {
        long long value = 0;
        if (!(std::cin >> value)) return 1;
        values.push_back(value);
    }
    long long total = std::accumulate(values.begin(), values.end(), 0LL);
    std::cout << total << std::endl;
    return 0;
}
